class Solution {
    ListNode* head;
public:
    Solution(ListNode* head) {
        this->head = head;
    }

    int getRandom() {
        int result = head->val;
        ListNode* cur = head->next;
        int i = 2;
        while (cur) {
            if (rand() % i == 0) {
                result = cur->val;
            }
            cur = cur->next;
            i++;
        }
        return result;
    }
};
